<?php
define('ABSPATH',__DIR__.'/');
class WP_Error {public $message;function __construct($c,$m,$d=null){$this->message=$m;}function get_error_message(){return $this->message;}}
function is_wp_error($v){return $v instanceof WP_Error;}function get_option($k,$d=null){return $GLOBALS['opts'][$k]??$d;}function update_option($k,$v,$a=false){$GLOBALS['opts'][$k]=$v;return true;}function sanitize_text_field($s){return trim(strip_tags($s));}function sanitize_textarea_field($s){return trim(strip_tags($s));}function wp_generate_uuid4(){return sprintf('aaaaaaaa-0000-4000-8000-%012d',++$GLOBALS['uuid']);}
class SBS_Finishing {static function error($c,$m,$n=422){return new WP_Error($c,$m);}}
class SBS_Final_Print {static function intact($a){return is_file($a['path'])&&hash_file('sha256',$a['path'])===$a['sha256'];}}
class SBS_Photo_Enhance {static function surface($v){return null;}}
class SBS_Storage {static $assets=array();static function base_dir(){return $GLOBALS['tmp'];}static function ensure_directories(){return true;}static function absolute_path($a){return $a['path'];}static function store_upload($f,$o,$n,$role,$label){$id=count(self::$assets)+1;$path=self::base_dir().'/'.$id.'.png';copy($f['tmp_name'],$path);return self::$assets[$id]=array('id'=>$id,'role'=>$role,'path'=>$path,'url'=>'/asset/'.$id,'filename'=>$f['name'],'mime'=>'image/png','sha256'=>hash_file('sha256',$path));}static function store_bytes($bytes,$name,$mime,$o,$n,$role,$label){$tmp=self::base_dir().'/thumb-temp.png';file_put_contents($tmp,$bytes);return self::store_upload(array('tmp_name'=>$tmp,'name'=>$name),$o,$n,$role,$label);}static function delete_asset($id){unlink(self::$assets[$id]['path']);unset(self::$assets[$id]);return true;}}
class SBS_Google_Drive {static $writes=0;static function mockup_source_files($id){return new WP_Error('access','No folder access');}static function save_mockup_pair($q,$r){self::$writes++;return new WP_Error('destination','No verified artwork folder');}}
class Q {private $p,$f;function __construct($p,$f=array()){$this->p=$p;$this->f=$f;}function get_param($k){return $this->p[$k]??null;}function get_file_params(){return $this->f;}}
function check($v,$m){if(!$v)throw new Exception($m);}
require dirname(__DIR__).'/includes/class-sbs-mockups.php';require dirname(__DIR__).'/includes/class-sbs-mockup-queue.php';
$GLOBALS['tmp']=sys_get_temp_dir().'/sbs-pair-'.bin2hex(random_bytes(5));mkdir($GLOBALS['tmp']);mkdir($GLOBALS['tmp'].'/finishing');$GLOBALS['uuid']=0;$GLOBALS['opts']=array();
try{
$im=new Imagick();$im->newImage(120,180,'white','png');$file=$GLOBALS['tmp'].'/source.png';file_put_contents($file,$im->getImageBlob());$upload=array('tmp_name'=>$file,'name'=>'Cruise-Tshirt-50.png','error'=>0,'size'=>filesize($file));$sourceHash=hash_file('sha256',$file);$pair=array();
foreach(array('men-model','men-flat','women-model','women-flat') as $category){$r=SBS_Mockup_Queue::templates(new Q(array('operation'=>'import','category'=>$category),array('file'=>$upload)));check(!is_wp_error($r),'Import failed');$id=$r['template']['id'];$pair[$category]=$id;$again=SBS_Mockup_Queue::templates(new Q(array('operation'=>'import','category'=>$category),array('file'=>$upload)));check($again['reused']&&$again['template']['id']===$id,'Exact duplicate imported twice');$r=SBS_Mockup_Queue::templates(new Q(array('operation'=>'calibrate','id'=>$id,'quad'=>array(array(.2,.2),array(.8,.2),array(.8,.8),array(.2,.8)),'colour'=>'#ffffff','lighting'=>true)));check(!is_wp_error($r),'Calibration failed');}
$asset=$r['template']['asset'];for($i=1;$i<=5;$i++){$record=array('uuid'=>'art-'.$i,'title'=>'Design '.$i,'series'=>'SB','links'=>array('sb_id'=>'SB'.str_pad((string)$i,4,'0',STR_PAD_LEFT)),'final_print'=>array('finished'=>array('asset'=>$asset,'approval'=>array('sha256'=>$asset['sha256']))));file_put_contents($GLOBALS['tmp'].'/finishing/art-'.$i.'.json',json_encode($record));}
$r=SBS_Mockup_Queue::queue(new Q(array('operation'=>'start','group'=>'men','templates'=>array($pair['men-model'],$pair['men-flat']),'artwork'=>array('art-1','art-2','art-3','art-4','art-5'),'preset'=>'Pinterest')));check(!is_wp_error($r),'Queue start failed');$queue=$r['queue'];check(count($queue['items'])===5&&empty($queue['items'][1]['outputs']),'Future item rendered');$locked=SBS_Mockup_Queue::templates(new Q(array('operation'=>'delete','id'=>$pair['men-model'],'confirm'=>true)));check(is_wp_error($locked),'Active queue template deleted');check(is_wp_error(SBS_Mockup_Queue::queue(new Q(array('operation'=>'approve','revision'=>$queue['revision'])))),'Unrendered pair approved');
foreach(array('Model','FlatLay') as $kind){$r=SBS_Mockup_Queue::output(new Q(array('queue'=>$queue['id'],'revision'=>$queue['revision'],'kind'=>$kind,'qa'=>'CHECK — inspect'),array('file'=>$upload)));check(!is_wp_error($r),'Output save failed');$queue=$r['queue'];check(strpos($queue['items'][0]['outputs'][$kind]['filename'],'SB0001-'.$kind.'-Pinterest-')===0,'Canonical filename incorrect');}
$revision=$queue['revision'];$r=SBS_Mockup_Queue::queue(new Q(array('operation'=>'download','revision'=>$revision,'kind'=>'Model')));$queue=$r['queue'];check($queue['index']===0&&$queue['items'][0]['status']==='ready','Download advanced or approved queue');$r=SBS_Mockup_Queue::queue(new Q(array('operation'=>'approve','revision'=>$queue['revision'])));$queue=$r['queue'];check($queue['index']===1&&$queue['items'][0]['status']==='approved'&&$queue['items'][0]['drive']['status']==='failed','Approval or distinct Drive failure lost');check(SBS_Google_Drive::$writes===1,'Duplicate Drive write');check(is_wp_error(SBS_Mockup_Queue::queue(new Q(array('operation'=>'approve','revision'=>$revision)))),'Stale tab advanced twice');
foreach(array('pause','resume','skip','previous','retry','discard') as $op){$r=SBS_Mockup_Queue::queue(new Q(array('operation'=>$op,'revision'=>$queue['revision'])));check(!is_wp_error($r),'Queue action failed: '.$op);$queue=$r['queue'];}check(hash_file('sha256',$file)===$sourceHash,'Original bytes changed');$cancel=SBS_Mockup_Queue::templates(new Q(array('operation'=>'delete','id'=>$pair['women-model'])));check(is_wp_error($cancel),'Unconfirmed deletion succeeded');$deleted=SBS_Mockup_Queue::templates(new Q(array('operation'=>'delete','id'=>$pair['women-model'],'confirm'=>true)));check(!is_wp_error($deleted)&&$deleted['deleted'],'Confirmed template deletion failed');check(is_file($file),'External source was deleted');$sync=SBS_Mockup_Queue::sync();check(count($sync['errors'])===4,'Drive access failures hidden');
echo "Reviewed pair queue: four categories, duplicate imports, calibration, five-item gate, separate downloads, canonical names, approval, Drive errors, stale revisions, pause/resume/skip/retry and guarded deletion passed.\n";
}finally{$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($GLOBALS['tmp'],FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::CHILD_FIRST);foreach($it as $f){$f->isDir()?rmdir($f->getPathname()):unlink($f->getPathname());}rmdir($GLOBALS['tmp']);}
